import { readdir, readFile, writeFile } from "node:fs/promises";
import { URL } from "node:url";
import { format } from "prettier";
// Bundle our additive schema for edge runtimes, which cannot read package files.
for (const backend of ["d1", "postgres"]) {
  const root = new URL(`../packages/storage/${backend}/`, import.meta.url);
  const files = (await readdir(new URL("migrations/", root)))
    .filter((f) => f.endsWith(".sql"))
    .sort();
  const statements = [];
  for (const file of files) {
    const sql = (
      await readFile(new URL(`migrations/${file}`, root), "utf8")
    ).replace(/--[^\n]*/g, "");
    for (const part of sql
      .split(";")
      .map((s) => s.trim())
      .filter(Boolean)) {
      if (!/^CREATE (TABLE|INDEX) /i.test(part))
        throw new Error(`Review non-additive schema change: ${file}`);
      statements.push(
        part.replace(
          /^CREATE (TABLE|INDEX) (?!IF NOT EXISTS)/i,
          "CREATE $1 IF NOT EXISTS ",
        ),
      );
    }
  }
  await writeFile(
    new URL("src/schema.generated.ts", root),
    await format(
      `// Generated by scripts/schema-bundle.mjs. Do not edit.\nexport const SCHEMA_VERSION = ${files.length};\nexport const SCHEMA_STATEMENTS: readonly string[] = ${JSON.stringify(statements, null, 2)};\n`,
      { parser: "typescript" },
    ),
  );
}
